fn lm_441(mut txt: Tpl::Text, items: &metamodelica::List<FMI::TypeDefinitions>) -> Result<Tpl::Text> {
    for lstElt_441 in items {
        ::match_deref::match_deref! { match lstElt_441 {
            i_fmiTypeDefinition => {
                txt = dumpFMITypeDefinition(txt, i_fmiTypeDefinition)?;
                txt = Tpl::nextIter(txt)?;
            }
            _ => return Err("lm_441: no case matched"),
        } }
    }
    Ok(txt)
}

